MQL:
db.stadium.aggregate([
  { $unwind: { path: "$concerts", preserveNullAndEmptyArrays: false } },
  { $unwind: { path: "$concerts.singers", preserveNullAndEmptyArrays: false } },
  { $group: {
      _id: "$_id",
      Name: { $first: { $ifNull: ["$Name", "(unknown)"] } },
      Capacity: { $first: "$Capacity" },
      singer_ids: { $addToSet: "$concerts.singers.Singer_ID" }
  } },
  { $project: { Name: 1, Capacity: 1, singer_count: { $size: "$singer_ids" } } },
  { $match: { Capacity: { $gt: 5000 } } },
  { $facet: {
      per_stadium: [ { $project: { _id: 0, Name: 1, singer_count: 1 } } ],
      avg_singers: [
        { $group: { _id: null, avg_count: { $avg: "$singer_count" } } }
      ]
  } },
  { $project: {
      kept: { $filter: {
        input: "$per_stadium",
        as: "s",
        cond: { $gt: ["$$s.singer_count", { $arrayElemAt: ["$avg_singers.avg_count", 0] }] }
      } }
  } },
  { $unwind: "$kept" },
  { $replaceRoot: { newRoot: "$kept" } }
])
